INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(5, 'frFR', 'Oh ! une cargaison envoyée par mon frère. Splendide ! La chance est avec moi aujourd''hui !', 0),
(97, 'frFR', 'Oui, $N ?', 0),
(98, 'frFR', 'Oui, $N ?', 0),
(109, 'frFR', 'Est-ce que par hasard...?', 0),
(219, 'frFR', 'Oui ?', 0),
(526, 'frFR', 'Avez-vous trouvé le fer de sancteforge dont vous aviez besoin ?', 0),
(567, 'frFR', 'Oui ?', 0),
(898, 'frFR', 'Oui ?', 0),
(908, 'frFR', 'Avez- vous réussi à localiser le Noyau de la Brasse ? Sans lui nous n''aurons aucune idée de l''emplacement précis du Marteau du crépuscule.', 0),
(909, 'frFR', 'Ah, rebonjour, $N. J''étais juste en train d''étudier les vagues, la mer, comme je le fais habituellement. Qu''est-ce qui vous amène à l''avant-poste ?', 0),
(934, 'frFR', 'Assistés des druides, l''arbre-oracle et l''archidruide surveillèrent avec attention la croissance de Teldrassil. Mais bien que nous possédions une nouvelle demeure, nos vies immortelles n''étaient pas restaurées.', 0),
(995, 'frFR', 'Oui, $N ?', 0),
(1265, 'frFR', 'Oui, $N ?', 0),
(1423, 'frFR', 'Vous avez quelque chose pour moi ?', 0),
(1489, 'frFR', 'Vos maîtres sont fous de vous envoyer ici, pour que je ne sois jamais un esclave du Fléau !', 0),
(1978, 'frFR', 'Oui ?', 0),
(2202, 'frFR', 'Vous avez les champignons magenta dont j''ai besoin pour mes travaux ? Pas de champignons, pas de récompense !', 0),
(2500, 'frFR', 'Avez-vous ce que je vous ai demandé ? Vous ne serez payé que lorsque vous m''aurez rapporté ces ingrédients.', 0),
(2583, 'frFR', 'Où sont les organes, $N ?', 0),
(2584, 'frFR', 'Où sont les organes, $N ?', 0),
(2586, 'frFR', 'Où sont les organes, $N ?', 0),
(2881, 'frFR', 'Je veux cinq de ces colliers tribaux que les trolls portent sur eux. Au cas où vous ne l''auriez pas compris, tuer un troll vous permettra sûrement d''en obtenir un !$B$BMontrez votre valeur aux Marteaux-hardis !', 0),
(3643, 'frFR', 'Une fois que j’aurai reçu et inspecté ce que vous devez fabriquer, vous deviendrez un ingénieur gnome diplômé, capable d’accéder à tous les secrets de tous les maîtres d’ingénierie gnome du monde !', 0),
(4022, 'frFR', '<Les yeux de Cyrus forment deux sphères embrasées.>', 0),
(4641, 'frFR', 'La carapace des scorpides n''est pas assez épaisse pour résister à une lame déterminée. Frappez fort, frappez juste et ils feront une proie facile.', 0),
(4982, 'frFR', 'Alors ?', 0),
(4987, 'frFR', 'Au nom du Cercle cénarien, je vous souhaite la bienvenue dans cette enclave, $C. Qu''est-ce qui vous amène ?', 0),
(5102, 'frFR', 'Est-ce fait ?', 0),
(5504, 'frFR', 'Ah, noble $C ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, vous pourrez acheter l’un de nos mantelets.', 0),
(5513, 'frFR', 'Ah, noble $C ! Avez-vous les marques de valeur demandées ? Lorsque vous me les aurez remises, vous pourrez acheter l’un de nos mantelets.', 0),
(5893, 'frFR', 'Êtes-vous entré dans la mine de Froide-dent dans le territoire de la Horde, $N ? Avez-vous pillé leurs fournitures ?', 0),
(7487, 'frFR', 'Vous devez mettre votre âme en harmonie avec le Cœur du Magma avant de pouvoir entrer.', 0),
(7815, 'frFR', 'Alors, cette chasse ?', 0),
(7905, 'frFR', 'Oui messire, puis-je vous aider ? Auriez-vous un coupon à échanger ?', 0),
(7907, 'frFR', 'Ça alors.', 0),
(8234, 'frFR', 'Je vous connais ?', 0),
(8388, 'frFR', 'Le sang versé par de grands guerriers n’a pas encore séché dans le bassin d’Arathi, et le fracas de l’acier résonne encore dans la vallée d’Alterac. Ne me faites pas perdre mon temps, à moins que vous n’apportiez des nouvelles du front !', 0),
(8417, 'frFR', 'Est-ce que Stoley a ma gnôle ?', 0),
(8499, 'frFR', 'Oh ! une cargaison envoyée par mon frère. Splendide ! La chance est avec moi aujourd''hui !', 0),
(8551, 'frFR', 'Hoe, $N ! Avez vous trouvé Gorlash ? Ce coffre était mon préféré, et il a un compartiment secret qui renferme mes plus grands trésors !', 0),
(8554, 'frFR', 'Avez vous mon coutelas, $N ?', 0),
(8580, 'frFR', 'Avez-vous récolté tous les échantillons ? Nous pouvons perdre Noggle d''une minute à l''autre !', 0),
(8609, 'frFR', 'Avez-vous le venin ?', 0),
(8747, 'frFR', 'Impressionnant, petit. Vous n’avez épargné aucun effort pour gagner les faveurs du Vol de bronze. Votre dévouement a été noté.$B$BLa chevalière du défenseur vous protègera des forces du mal.$B$BMais attention, une fois que vous aurez choisi votre voie, vous ne pourrez plus revenir en arrière, même si vous changez d’avis.', 0),
(8752, 'frFR', 'Impressionnant, petit. Vous n’avez épargné aucun effort pour gagner les faveurs du Vol de bronze. Votre dévouement a été noté.$B$BLa chevalière du conquérant rendra vos attaques physiques beaucoup plus meurtrières.$B$BMais attention, une fois que vous aurez choisi votre voie, vous ne pourrez plus revenir en arrière, même si vous changez d’avis.', 0),
