INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(526, 'frFR', 'Oh ! Vous en avez trouvé ! Et si nous le fondions pour en faire quelque chose d''utile, maintenant ?', 0),
(908, 'frFR', 'C''est exactement ce dont j''avais besoin ! C''est une incroyable source d''informations dont nous tirerons beaucoup de bien. Quel que soit le maléfice secret du Marteau du crépuscule, croyez-moi, mes camarades et moi saurons bientôt tout !$B$BVous avez bien agi, et le Cercle terrestre souhaite vraiment que vous nous aidiez ! Vous avez également aidé la Horde toute entière et vous avez toutes les raisons d''éprouver de la fierté.', 0),
(909, 'frFR', 'C''est... C''est une sacrée trouvaille, $N.$B$BVous avez acquis ceci auprès du baron Aquanis, à Brassenoire, dites-vous ? Le baron Aquanis a longtemps été considéré comme un élémentaire corrompu, ce globe montrera exactement ce qui l''a souillé. Ce ne sera pas une surprise si l''on découvre que c''est le Marteau du crépuscule, mais nous découvrirons également comment cela s''est passé.$B$BVous avez bien fait de m''apporter ceci. Veuillez prendre ça, ainsi que la gratitude sincère du Cercle terrestre.', 0),
(1127, 'frFR', 'Ah, très bien ! Voici votre salaire.$B$BEt voilà un petit extra... pour votre discrétion.', 0),
(1499, 'frFR', 'Vous avez bien agi, $N.$B$BLes vils quasits ne sont que des marionnettes dirigées par des puissances agissant au sein de la Lame ardente, mais votre succès en présage de plus grands à l''avenir.', 0),
(2881, 'frFR', 'Voilà ce dont je parlais ! Ces colliers prouvent que vous voulez travailler pour nous. Nous, les Marteaux-hardis, respectons nos alliés.$B$BContinuez ainsi et vous entrerez dans nos bonnes grâces.', 0),
(3634, 'frFR', 'Oh, un jeune ingénieur qui veut poursuivre l''étude de la seule, la vraie discipline d''ingénierie ! Pardonnez ce ton mélodramatique, mon ami. Alors que notre situation devient de plus en plus difficile, c''est toujours une joie de voir qu''un autre ingénieur répond à l''appel de clairon de la véritable ingénierie !', 0),
(3763, 'frFR', 'Bien, $C… Puisque vous avez été informé que je dirigeais en personne ces recherches, vous êtes évidemment venu aussi vite que possible.$B$BMaintenant que vous êtes là, écoutez attentivement. J''ai horreur de me répéter.', 0),
(3785, 'frFR', 'Bon travail, $N. Je les remettrai à l''archidruide en personne lorsqu''il en aura besoin. En attendant, veuillez accepter ceci comme gage de gratitude du Cercle cénarien.$B$BNous avons pour l''heure un besoin constant de Fibres d''aurore. Si vous souhaitez continuer à nous en fournir, revenez lorsque vous en aurez cultivé plus.', 0),
(3787, 'frFR', 'Je vous remercie d''être venu, las voyageur ! Permettez-moi de me présenter. Je me nomme Quintis Gentecime et suis druide et humble serviteur de Malfurion et du Cercle cénarien. Mes collègues (le général Shandris Pennelune et le Protectorat, vous avez peut-être entendu parler d''eux !) et moi-même souhaitions vous entretenir à propos des travaux que vous effectuez pour Fandral Forteramure à Darnassus.$B$BAvant de poursuivre, j''aimerais vous demander de garder secrète cette conversation. Si cela ne vous pose pas de problèmes, alors nous pouvons commencer.', 0),
(5403, 'frFR', 'Félicitations, $N. Je suis heureux de vous donner une marque de valeur de l''Aube d''argent !$B$BChaque marque de valeur attribuée à un bénéficiaire méritant est un signe que le vent tourne contre le Fléau. Avec un nombre de plus en plus grand de héros combattant le Fléau sur ses propres terres, l''Aube d''argent sera assurément en bonne position quand le temps sera venu de porter l''attaque ultime contre le Fléau. J''espère que la valeur dont vous avez fait preuve pour gagner votre marque fera merveille à nouveau ce jour-là.', 0),
(6123, 'frFR', 'C''est bien, $N, il y en a suffisamment pour un grand nombre de doses de baume – tout du moins assez pour commencer à changer les choses.$B$BPréparer un remède à un poison peut être bien difficile car chacun réagit à un antidote spécifique. Comment imaginer neutraliser un poison sans se soucier des ingrédients nécessaires pour élaborer l''antidote ?$B$BMaintenant, laissez-moi travailler !', 0),
(7462, 'frFR', 'Vous ouvrez le coffre pour trouver…', 0),
(7487, 'frFR', 'Je peux maintenant vous transporter au Cœur du Magma. Demandez et vous serez exaucé.', 0),
(8270, 'frFR', 'Excellent ! Vous avez prouvé que vous êtes un allié de valeur dans nos préparatifs de guerre contre les silithides.', 0),
(8274, 'frFR', 'Je vous suis sincèrement reconnaissante. Vos efforts pour aider le Fort cénarien démontrent un réel courage.', 0),
(8542, 'frFR', 'Je vous suis sincèrement reconnaissante. Vos efforts pour aider le Fort cénarien démontrent un réel courage.', 0),
(8549, 'frFR', 'Ce n''était pas chose facile, pourtant vous avez excellé. Mais ne pensez pas trop vite que vous m''avez impressionné, $N.', 0),
(8580, 'frFR', 'Croisez les doigts, mon ami ! Pourvu que Noggle soit sauvé !', 0),
(8604, 'frFR', 'Je vous suis sincèrement reconnaissante. Vos efforts pour aider le Fort cénarien démontrent un réel courage.', 0),
(8609, 'frFR', 'Bravo, vous l''avez !', 0),
(8904, 'frFR', 'Mes craintes étaient justifiées. C’est incroyable. Comment est-ce possible ? Laissez-moi réfléchir un moment. Il doit y avoir une raison à tout ceci.', 0),
(9221, 'frFR', 'Bonne journée, $N. Ce fut un plaisir de faire des affaires avec vous.', 0),
(9225, 'frFR', 'Bonne journée, $N. Ce fut un plaisir de faire des affaires avec vous.', 0),
(11072, 'frFR', 'Excellent ! Prenez ceci. J''ai mis dans ce paquet les objets que vous avez rassemblés. Ils vous permettront d''invoquer Terokk.$B$BPrenez garde, $N. Il est le plus puissant des arakkoa à avoir jamais vu le jour. Ne le sous-estimez pas !', 0),
(11400, 'frFR', 'Beau travail, $N... Vous avez gagné la confiance des brasseurs du festival, obtenant le droit d''acheter un Bélier de la fête des Brasseurs.', 0),
(11517, 'frFR', 'C''est Portonuus qui vous envoie ? Bien, nous n''avons pas de temps à perdre !', 0),
(11542, 'frFR', 'Très bien, $N. Il s''écoulera un bon moment avant que le port ne reçoive des renforts.', 0),
(11545, 'frFR', 'Votre âme est vertueuse, $N. Il est aisé d''oublier ceux qui sont tombés lorsqu''on est dans le tumulte de la guerre ou dans l''euphorie de la victoire. Les amis et les familles des morts vous remercient.', 0),
(11922, 'frFR', 'Bravo, vous l’avez fait ! Super ! Peut-être bien que l’an prochain, vous devriez vous faire embaucher à la fête !', 0),
(12193, 'frFR', 'Oooh, ce n’est qu’un bon-cadeau pour un bock… Peut-être que vous préférez vous faire un peu désirer. Enfin… Voici la chope de cette année.$B$BMais j’ai l’impression que je vais vous revoir. Après tout, si vous voulez échanger des bons de la fête des Brasseurs, je suis toute à vous…$B$BOu peut-être à lui…$B$BOooohhhh… ou à lui, là…', 0),
(12194, 'frFR', 'Qu’est-ce que c’est ? Un bon pour un bock ? Alors vous aimez bien boire ? Super ! Quand je vous aurai donné ce bock, allez boire quelques verres ! Et puis quelques autres. Peut-être même quelques-uns de plus ensuite. Après, et ça c’est important, revenez me voir.$B$BJe sais que vous finirez bien par revenir. Si vous voulez échanger vos jetons de la fête des Brasseurs,vous devrez passer me voir.$B$BQuoi qu’il en soit, voilà le bock, et n’oubliez pas de repasser.', 0),
(12785, 'frFR', 'Ah, très bien. Les maladies que cette tête pourrie transporte sont mortelles, mais nous ne devons pas être timides face au danger ou à ce que nous trouvons déplaisant. Un jour, $N, vous apprendrez que la damnation est le chemin du salut...', 0),
(12788, 'frFR', 'Ah, très bien. Les maladies que cette tête pourrie transporte sont mortelles, mais nous ne devons pas être timides face au danger ou à ce que nous trouvons déplaisant. Un jour, $N, vous apprendrez que la damnation est le chemin du salut...', 0),
(13429, 'frFR', '<De l''énergie pulse en Xi''ri et vous sentez un objet se matérialiser dans vos mains. C''est le médaillon que vous avez remis à A''dal de la part d''Akama, et sa puissance a été accrue par la magie des naaru. Les Sha''tar vous ont confié le Médaillon de Karabor, et avec lui un accès au Temple noir.>', 0),
(14089, 'frFR', 'Alors, voulez-vous commencer l''entraînement pour devenir Apprenti cavalier ?', 0),
(14179, 'frFR', 'Nous voilà un pas plus près de la victoire totale contre la Horde. Nous ne devons pas permettre à l’ennemi de mettre un pied dans la porte, sur ce monde ou sur un autre.', 0),
(14180, 'frFR', 'Excellent travail, $N. L’intégrité de nos frontières doit être maintenue à n’importe quel prix !', 0),
(14181, 'frFR', 'Vous avez apporté de l’honneur à la Horde, $N. Votre victoire de ce jour nous assurera de mille autres victoires demain !', 0),
(14182, 'frFR', 'Vous nous faites honneur à tous, $N. Nous devons montrer à l’ennemi que nous le combattrons partout où nous le trouverons.', 0),
(24216, 'frFR', 'La Horde a une dette envers vous, $N. Nous sommes fiers du courage que vous avez montré pour défendre nos terres.', 0),
(24218, 'frFR', 'Excellent travail, $N. L’intégrité de nos frontières doit être maintenue à n’importe quel prix !', 0),
(24219, 'frFR', 'Excellent travail, $N. L’intégrité de nos frontières doit être maintenue à n’importe quel prix !', 0),
(24221, 'frFR', 'Vous avez apporté de l’honneur à la Horde, $N. Votre victoire de ce jour nous assurera de mille autres victoires demain !', 0),
(24224, 'frFR', 'Excellent travail, $N. L’intégrité de nos frontières doit être maintenue à n’importe quel prix !', 0),
(24225, 'frFR', 'La Horde a une dette envers vous, $N. Nous sommes fiers du courage que vous avez montré pour défendre nos terres.', 0),
(24226, 'frFR', 'Vous avez apporté de l’honneur à la Horde, $N. Votre victoire de ce jour nous assurera de mille autres victoires demain !', 0),
(24426, 'frFR', 'Il n’existe pas d’honneur plus grand que de repousser les envahisseurs des territoires de la Horde. Nous saluons votre courage dans l’aide que vous avez apportée à nos troupes aujourd’hui !', 0),
(24427, 'frFR', 'Précisément c’que j’espérais entendre ! Une victoire dans la vallée d’Altérac, même temporaire, est cruciale dans notre stratégie globale contre la Horde.', 0),
(24857, 'frFR', 'C''est en effet bien inquiétant ! Mais grâce à cette information, nous pouvons appeler à l''aide nos frères de Sabot-de-sang et contrecarrer ce projet d''attaque. Vous venez de sauver la vie de nombreux taurens, $N.', 0),
(25092, 'frFR', 'Bien joué, $N, mais pour chaque élément apaisé, un autre surgit, encore plus agité que le précédent. Notre solution n’est qu’un emplâtre sur une jambe de bois. J’espère que mes confrères du Cercle terrestre ont mieux progressé que nous.', 0);
